"use client";

import Link from "next/link";
import Image from "next/image";
import { usePathname } from "next/navigation";
import { motion, useReducedMotion } from "motion/react";
import { FOCUSABLE_CHROME } from "@/lib/a11y";
import { duration, easeOut } from "@/lib/motion";
import { PRIMARY_NAV } from "@/lib/nav";
import { site } from "@/lib/site";
import { ThemeToggle } from "@/components/theme-toggle";

/** P4 nav-chrome r2 — asymmetric rail + quiet rule (critic: bar won r1). */
export function SiteHeader() {
  const pathname = usePathname();
  const reduce = useReducedMotion();

  return (
    <motion.header
      className="site-header pointer-events-none sticky top-0 z-30"
      initial={reduce ? { opacity: 0 } : { opacity: 0, y: -6 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{
        duration: reduce ? 0.18 : duration.chromeEnter,
        ease: easeOut,
      }}
    >
      <div className="site-header-rail pointer-events-auto">
        <Link
          href="/"
          aria-label={`${site.name} — Home`}
          className="header-brand group flex min-h-8 items-center gap-2.5 no-underline"
        >
          <Image
            src={site.avatar}
            alt=""
            width={24}
            height={24}
            className="header-avatar-img size-6 rounded-full"
          />
          <span className="header-handle hidden text-[13px] font-medium tracking-[-0.015em] text-foreground min-[420px]:inline">
            {site.handle}
          </span>
        </Link>

        <div className="site-header-end">
          <nav
            aria-label={FOCUSABLE_CHROME.primaryNavLabel}
            className="site-nav"
          >
            {PRIMARY_NAV.map((item) => {
              const active =
                item.href === "/"
                  ? pathname === "/"
                  : pathname.startsWith(item.href);

              return (
                <Link
                  key={item.href}
                  href={item.href}
                  aria-current={active ? "page" : undefined}
                  data-active={active}
                  className="nav-item"
                >
                  <span className="nav-item-label">{item.label}</span>
                  {active && !reduce ? (
                    <motion.span
                      layoutId="nav-active-signal"
                      className="nav-item-signal"
                      transition={{
                        type: "spring",
                        duration: 0.36,
                        bounce: 0.1,
                      }}
                      aria-hidden
                    />
                  ) : active ? (
                    <span className="nav-item-signal" aria-hidden />
                  ) : null}
                </Link>
              );
            })}
          </nav>

          <ThemeToggle />
        </div>
      </div>
    </motion.header>
  );
}
