"use client";

import { useSyncExternalStore } from "react";
import { useTheme } from "next-themes";
import { Moon, Sun } from "@/components/icons";

const emptySubscribe = () => () => {};

/**
 * Explicit 32px theme control (nav-chrome r2) — dark is the identity default;
 * a manual override persists via next-themes (`portfolio-theme`).
 */
export function ThemeToggle() {
  const { resolvedTheme, setTheme } = useTheme();
  const mounted = useSyncExternalStore(
    emptySubscribe,
    () => true,
    () => false,
  );
  const isDark = resolvedTheme === "dark";

  return (
    <button
      type="button"
      disabled={!mounted}
      className="theme-toggle"
      data-state={mounted ? (isDark ? "dark" : "light") : "pending"}
      aria-label={
        !mounted
          ? "Theme"
          : isDark
            ? "Switch to light theme"
            : "Switch to dark theme"
      }
      title={
        !mounted
          ? "Theme"
          : isDark
            ? "Switch to light theme"
            : "Switch to dark theme"
      }
      onClick={() => {
        if (!mounted) return;
        setTheme(isDark ? "light" : "dark");
      }}
    >
      <span
        className="theme-toggle-icons"
        data-theme={mounted ? (isDark ? "dark" : "light") : undefined}
      >
        {mounted ? (
          <>
            <Sun
              size={15}
              weight="bold"
              aria-hidden
              className="theme-toggle-icon theme-toggle-sun"
            />
            <Moon
              size={15}
              weight="bold"
              aria-hidden
              className="theme-toggle-icon theme-toggle-moon"
            />
          </>
        ) : (
          <span className="theme-toggle-skeleton" aria-hidden />
        )}
      </span>
    </button>
  );
}
