/* ── Nav chrome (Ink Signal · r1 / P4) ──────────────────────────────────────
   Floating pill: avatar + Home/Blog/Projects + quiet theme control.
   Domain lock — not a full-width rail. Precise elevation, not heavy glass.
*/
.header-pill {
  border: 1px solid color-mix(in srgb, var(--color-border) 88%, transparent);
  background: color-mix(in srgb, var(--color-background) 88%, transparent);
  backdrop-filter: blur(10px) saturate(1.12);
  -webkit-backdrop-filter: blur(10px) saturate(1.12);
  box-shadow:
    0 1px 0 0 color-mix(in srgb, var(--color-foreground) 5%, transparent) inset,
    0 2px 4px -1px rgb(0 0 0 / 0.32),
    0 12px 28px -14px rgb(0 0 0 / 0.58);
  transition:
    background-color var(--duration-theme) var(--ease-out-quad),
    border-color var(--duration-theme) var(--ease-out-quad),
    box-shadow var(--duration-theme) var(--ease-out-quad);
}

.light .header-pill {
  background: color-mix(in srgb, var(--color-background) 92%, transparent);
  border-color: color-mix(in srgb, var(--color-border) 95%, transparent);
  box-shadow:
    0 1px 0 0 rgb(255 255 255 / 0.7) inset,
    0 1px 2px rgb(23 20 16 / 0.04),
    0 10px 24px -12px rgb(23 20 16 / 0.14);
}

.header-avatar-img {
  box-shadow: 0 0 0 1px color-mix(in srgb, var(--color-border) 90%, transparent);
  transition:
    transform var(--duration-hover) var(--ease-out-quad),
    box-shadow var(--duration-hover) var(--ease-out-quad);
}

@media (hover: hover) and (pointer: fine) {
  .header-brand:hover .header-avatar-img {
    transform: scale(1.06);
    box-shadow: 0 0 0 1px color-mix(in srgb, var(--color-foreground) 18%, transparent);
  }

  .header-brand:hover .header-handle {
    opacity: 0.72;
  }
}

.header-handle {
  transition: opacity var(--duration-hover) var(--ease-out-quad);
}

.header-rule {
  background: color-mix(in srgb, var(--color-border) 92%, transparent);
  flex-shrink: 0;
}

.nav-item {
  position: relative;
  display: inline-flex;
  min-height: 2rem;
  align-items: center;
  border-radius: 9999px;
  padding: 0 0.7rem;
  font-size: 13px;
  letter-spacing: -0.012em;
  line-height: 1;
  text-decoration: none;
  color: var(--color-muted);
  transition: color var(--duration-hover) var(--ease-out-quad);
}

@media (min-width: 640px) {
  .nav-item {
    padding: 0 0.8rem;
  }
}

@media (hover: hover) and (pointer: fine) {
  .nav-item:hover {
    color: var(--color-foreground);
  }

  .nav-item:not([data-active="true"]):hover {
    background: color-mix(in srgb, var(--color-surface-hover) 70%, transparent);
  }
}

.nav-item:focus-visible {
  outline: 2px solid var(--color-accent);
  outline-offset: 2px;
}

.nav-item[data-active="true"] {
  color: var(--color-foreground);
  font-weight: 500;
}

.nav-item-active {
  position: absolute;
  inset: 0;
  border-radius: 9999px;
  background: var(--color-surface-hover);
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--color-border) 70%, transparent);
  pointer-events: none;
}

.light .nav-item-active {
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--color-border) 85%, transparent);
}

.nav-item-label {
  display: inline-block;
  transition: transform var(--duration-press) var(--ease-out);
}

.nav-item:active .nav-item-label {
  transform: scale(0.97);
}

/* Theme toggle — intentional quiet control inside the pill */
.theme-toggle {
  position: relative;
  display: inline-flex;
  flex-shrink: 0;
  width: 2rem;
  height: 2rem;
  align-items: center;
  justify-content: center;
  border: 0;
  border-radius: 9999px;
  background: transparent;
  color: var(--color-muted);
  cursor: pointer;
  transition:
    color var(--duration-hover) var(--ease-out-quad),
    background-color var(--duration-hover) var(--ease-out-quad),
    transform var(--duration-press) var(--ease-out);

