@import "tailwindcss";

@custom-variant dark (&:where(.dark, .dark *));

/*
  Visual system: "Ink Signal".
  Dark is the identity — warm ink depth, structural field, amber signal.
  One decisive accent (not portfolio blue / cyan / purple / cream+terracotta).
  Light is the same system inverted with equal craft.
  P2 owns color tokens + .site-backdrop only; fonts stay with P1.
*/
@theme {
  /* Ink Signal type — P1 owns these font tokens (r2: Fraunces display) */
  --font-display: var(--font-display-face), "Fraunces", ui-serif, Georgia, serif;
  --font-sans: var(--font-sans-face), "Schibsted Grotesk", ui-sans-serif,
    system-ui, sans-serif;
  --font-mono: var(--font-mono-face), "JetBrains Mono", ui-monospace, monospace;

  /* Warm ink depths — charcoal with brown undertone, not cold gray */
  --color-background: #07080b;
  --color-background-muted: #0e0c0a;
  --color-surface: #141210;
  --color-surface-hover: #1b1814;
  --color-foreground: #f0ebe4;
  --color-muted: #9a9288;
  --color-faint: #6e675e;
  --color-border: #2a2620;
  --color-border-strong: #3c352c;
  /* Signal amber — one decisive accent */
  --color-accent: #e8a23a;
  --color-accent-muted: #f0bf6a;
  --color-accent-foreground: #0a0908;
  --color-link: #f0ebe4;

  /* Heatmap — full amber ramp (empty → signal) */
  --color-activity-0: #161310;
  --color-activity-1: #3d2a0e;
  --color-activity-2: #6f4a12;
  --color-activity-3: #b0781c;
  --color-activity-4: #e8a23a;

  /* Atmosphere field tokens (consumed by .site-backdrop) */
  --field-color: rgb(232 162 58 / 0.055);
  --grid-color: rgb(240 235 228 / 0.045);
  --glow-color: rgb(232 162 58 / 0.16);
  --ink-wash: rgb(18 12 6 / 0.62);
  --vignette-color: rgb(0 0 0 / 0.62);
  --grain-opacity: 0.42;

  /* Motion language (P7) — quiet craft, three beats only */
  --ease-out: cubic-bezier(0.23, 1, 0.32, 1);
  --ease-out-expo: cubic-bezier(0.16, 1, 0.3, 1);
  --ease-out-quad: cubic-bezier(0.25, 1, 0.5, 1);
  --duration-press: 140ms;
  --duration-hover: 160ms;
  --duration-theme: 240ms;
  --duration-enter: 420ms;
}

/* Light — same Ink Signal system inverted, not an afterthought */
.light {
  --color-background: #f2f0ec;
  --color-background-muted: #e8e4de;
  --color-surface: #faf8f5;
  --color-surface-hover: #ebe6df;
  --color-foreground: #14120e;
  --color-muted: #5c564c;
  --color-faint: #746c62;
  --color-border: #ddd6cc;
  --color-border-strong: #c4bbb0;
  --color-accent: #c47e1a;
  --color-accent-muted: #9a6010;
  --color-accent-foreground: #ffffff;
  --color-link: #14120e;

  --color-activity-0: #e6e1d8;
  --color-activity-1: #f0dfb8;
  --color-activity-2: #e8c878;
  --color-activity-3: #d49a2e;
  --color-activity-4: #c47e1a;

  --field-color: rgb(196 126 26 / 0.07);
  --grid-color: rgb(20 18 14 / 0.055);
  --glow-color: rgb(196 126 26 / 0.14);
  --ink-wash: rgb(232 226 216 / 0.7);
  --vignette-color: rgb(60 48 28 / 0.14);
  --grain-opacity: 0.28;
}

@layer base {
  html {
