  "/Users/dhruv2mars/.agent-browser/browsers/chrome-148.0.7778.97/Google Chrome for Testing.app/Contents/MacOS/Google Chrome for Testing";

await mkdir(OUT, { recursive: true });

const browser = await chromium.launch({
