  args: ["--disable-dev-shm-usage", "--no-sandbox"],
});

async function shot(opts: {
  file: string;
  width: number;
  height: number;
  theme: "dark" | "light";
  clip?: { x: number; y: number; width: number; height: number };
}) {
  const context = await browser.newContext({
    viewport: { width: opts.width, height: opts.height },
    colorScheme: opts.theme,
    deviceScaleFactor: 1,
  });
  await context.addInitScript((theme) => {
    localStorage.setItem("portfolio-theme", theme);
  }, opts.theme);
  const page = await context.newPage();
  await page.goto("http://localhost:3000/", {
    waitUntil: "domcontentloaded",
    timeout: 20000,
  });
  await page.waitForSelector(".site-header", { timeout: 15000 });
  await page.evaluate((theme) => {
    document.documentElement.classList.remove(
      theme === "dark" ? "light" : "dark",
    );
    document.documentElement.classList.add(theme);
    document
      .querySelector(".theme-toggle-icons")
      ?.setAttribute("data-theme", theme);
    const btn = document.querySelector("button.theme-toggle");
    if (btn) {
      btn.setAttribute("data-state", theme);
      btn.setAttribute(
        "aria-label",
        theme === "dark" ? "Switch to light theme" : "Switch to dark theme",
      );
    }
    window.scrollTo(0, 0);
  }, opts.theme);
  await page.waitForTimeout(700);
  const probe = await page.evaluate(() => ({
    nav: [...document.querySelectorAll(".nav-item")].map((n) =>
      (n as HTMLElement).innerText.trim(),
    ),
    header: !!document.querySelector(".site-header"),
    pill: !!document.querySelector(".header-pill"),
    signal: !!document.querySelector(".nav-item-signal"),
    toggle: (() => {
      const b = document.querySelector(
        "button.theme-toggle",
      ) as HTMLElement | null;
      if (!b) return null;
      const r = b.getBoundingClientRect();
      return {
        w: Math.round(r.width),
        h: Math.round(r.height),
        label: b.getAttribute("aria-label"),
      };
    })(),
    h1: document.querySelector("h1")?.textContent?.slice(0, 40),
  }));
  console.log(opts.file, JSON.stringify(probe));
  if (
    !probe.header ||
    probe.pill ||
    probe.nav.join("/") !== "Home/Blog/Projects" ||
    !probe.toggle ||
    probe.toggle.w !== 32 ||
    probe.toggle.h !== 32
  ) {
    throw new Error(`Probe failed for ${opts.file}: ${JSON.stringify(probe)}`);
  }
  await page.screenshot({ path: `${OUT}/${opts.file}`, clip: opts.clip });
  await context.close();
}

